UPDATE folder f
INNER JOIN folder root ON root.id = #{parentId}
SET
    f.level = f.level + (#{parentLevel} - root.level),
    f.path = CONCAT(
        #{parentPath},
        SUBSTRING(f.path, CHAR_LENGTH(root.path) + 1)
    )
WHERE f.author_id = #{authorId}
    AND (
        f.path = root.path
        OR f.path LIKE CONCAT(root.path, '/%')
    )

